// MCP over HTTP.
//
// `brain mcp` speaks stdio, which means the only thing that can reach a brain
// is a process the user launched on the same machine. That is a real limit: a
// teammate, a second machine, or an agent running anywhere else simply cannot
// query it. mem0, cognee and supermemory all expose remote MCP.
//
// It is also the most dangerous gap on the list to close, and the design says
// so throughout. A brain holds repository source, agent transcripts, prompts
// and commit history. An HTTP endpoint in front of that is a door, and the
// whole question is who gets to walk through it. So:
//
//   - It does not exist unless asked for. No flag, no listener. `brain mcp`
//     keeps speaking stdio and keeps making no network calls, which is what
//     SECURITY.md promises.
//   - It binds loopback unless explicitly told otherwise. A bare port means
//     127.0.0.1, never 0.0.0.0 — the difference between "my other terminal"
//     and "everyone on the coffee shop wifi" should not be a default.
//   - It always requires a bearer token. There is no unauthenticated mode, not
//     even on loopback: every process on the machine shares loopback, and
//     "localhost is safe" is how a brain gets read by a browser tab.
//   - Reaching a non-loopback interface needs a second, separate flag. Two
//     deliberate acts, because that one is genuinely different in kind.
//
// The handler reuses handleMCPMessage, the same dispatch stdio uses, so the two
// transports cannot drift apart in what they expose.

const (
	mcpHTTPTokenEnv = "ENTIRE_BRAIN_MCP_TOKEN"
	// Requests are bounded: an MCP message is small, and an unbounded body on a
	// local daemon is a trivial way to exhaust memory.
	mcpHTTPMaxBodyBytes = 4 << 20
	mcpHTTPReadTimeout  = 30 * time.Second
	mcpHTTPWriteTimeout = 120 * time.Second
	mcpHTTPIdleTimeout  = 90 * time.Second
)

// mcpHTTPConfig is the resolved, validated listener configuration. Building it
// is separated from serving so the safety rules are testable without opening a
// socket.
		},
		{
			"name": "brain_remember",
			// The one write an agent actually needs. Every other writing tool
			// here rebuilds derived state; this is the only way to record
			// something learned, and without it a session's conclusions die
			// with the session while `entire brain remember` sits in the CLI
			// where no agent can reach it.
			//
			// path is required rather than inferred. The CLI can classify a
			// fact by shelling out to a coding agent, and doing that from an
			// MCP call would spend model tokens the caller never asked for,
			// inside a tool whose whole point is that it is deterministic.
			// The caller already knows what it learned.
			"description": "Record a durable fact about this repository so it survives the session. The only tool here that writes memory rather than derived state; read the result back with brain_query source=fact, or brain_get by id. path is a taxonomy path shaped category.subcategory.type, e.g. constraints.retry.policy; a path outside this repository's taxonomy is refused with the valid categories named (by default architecture, constraints, preferences, project, workflow). Facts are stored per branch and anchored to the current commit.",
			"inputSchema": objectSchema([]string{"fact", "path"}, map[string]any{
				"fact":   stringArg("fact", "The durable fact, as one self-contained sentence"),
				"path":   stringArg("path", "Taxonomy path: category.subcategory.type, comma-separated for several"),
				"kind":   enumArg("kind", "Fact kind; inferred when omitted", []string{"decision", "invariant", "gotcha", "preference", "convention"}),
				"branch": branchArg(),
				"global": boolArg("global", "Record outside every repository so the fact applies everywhere (a preference, a team convention, an environment detail). Cannot be combined with branch."),
			}),
		},
		{
			"name":        "brain_search_code",
			"description": "Alias for brain_code; search indexed source symbols with compact records by default. Set details=true for full provider records.",
			"description": "Diff-less review (versioned schema_version contract) of the current working tree against brain memory, not a branch/base diff. Returns severity-ranked suspected regressions with provenance.",
			"inputSchema": objectSchema([]string{"query"}, map[string]any{"query": stringArg("query", "What to review plus the relevant symbols/identifiers"), "limit": integerArg("limit", "Maximum findings"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (lower confidence, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
		},
		{
			"name":        "brain_workspace_regressions",
			"description": "Flag suspected regressions across every repo in a local multi-repo workspace (each brain's memory vs that repo's current tree). Tolerates sessions-only brains; results are aggregated by repo_key. Allows registered sibling checkouts when the bound repo is a workspace member; other workspaces need ENTIRE_BRAIN_MCP_ALLOW_CROSS_REPO.",
			"inputSchema": objectSchema([]string{"workspace", "query"}, map[string]any{"workspace": stringArg("workspace", "Workspace name"), "query": stringArg("query", "Task description plus the failing symbols/identifiers"), "limit": integerArg("limit", "Maximum suspected regressions per repo"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (higher recall, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
		},
		{
			"name":        "brain_workspace_graph",
			"description": "Return per-repo graph metadata plus shared external contracts and cross_edges for a local multi-repo workspace. Allows registered sibling checkouts when the bound repo is a workspace member; other workspaces need ENTIRE_BRAIN_MCP_ALLOW_CROSS_REPO.",
			"inputSchema": objectSchema([]string{"workspace"}, map[string]any{"workspace": stringArg("workspace", "Workspace name"), "limit": integerArg("limit", "Maximum contracts/cross_edges")}),
		},
		{
			"name":        "brain_workspace_review",
			"description": "Cross-repo diff-less review (versioned contract) of each local workspace repo's current tree against its brain memory. Returns severity-ranked suspected regressions per repo. Allows registered sibling checkouts when the bound repo is a workspace member; other workspaces need ENTIRE_BRAIN_MCP_ALLOW_CROSS_REPO.",
			"inputSchema": objectSchema([]string{"workspace", "query"}, map[string]any{"workspace": stringArg("workspace", "Workspace name"), "query": stringArg("query", "What to review plus the relevant symbols/identifiers"), "limit": integerArg("limit", "Maximum findings per repo"), "include_deletions": map[string]any{"type": "boolean", "description": "Also flag deleted assignments (lower confidence, noisier)", "title": "include_deletions"}, "location_only": map[string]any{"type": "boolean", "description": "Return only the suspected file:line, not the expected/current values", "title": "location_only"}}),
		},
